function formatAjvError(e: ErrorObject): string {
  const params = e.params as Record<string, unknown>;
  const path = e.instancePath.replace(/^\//, '').replace(/\//g, '.');

  if (e.keyword === 'required' && typeof params.missingProperty === 'string') {
    const fullPath = path ? `${path}.${params.missingProperty}` : params.missingProperty;
    return `${fullPath} is required`;
  }
  return `${path || 'input'} ${e.message}`;
}

